/**
 * Template Selector Component
 * Selects and manages templates
 *
 * @version 1.0.0
 * @date 2026-01-29
 */

import { fetchTemplates, type Template } from '@shared/api/templateApi';
import { Input, EmptyState } from '@shared/ui';
import { ConfirmDialog } from '@shared/ui/ConfirmDialog/ConfirmDialog';
import React, { useState, useEffect, useCallback } from 'react';

import TemplateEditor from './TemplateEditor';

import './TemplateSelector.css';

/**
 * Template interface
 */
interface Template {
  id: string | number;
  name: string;
  type?: string;
  tags?: string[];
  description?: string;
  created_at: string;
}

/**
 * Confirm State interface
 */
interface ConfirmState {
  open: boolean;
  template: Template | null;
  title: string;
  message: string;
}

/**
 * Template Selector Props interface
 */
interface TemplateSelectorProps {
  gameGid: number | string;
  onTemplateSelect?: (template: Template) => void;
  currentTemplateId?: string | number;
  onEditTemplate?: (template: Template) => void;
  onDeleteTemplate?: (template: Template) => void;
  onCloneTemplate?: (template: Template) => void;
  onCreateTemplate?: (template: Partial<Template>) => void;
  onApplyTemplate?: (template: Template) => Promise<{ success: boolean }>;
}

export default function TemplateSelector({
  gameGid,
  onTemplateSelect,
  onEditTemplate,
  onDeleteTemplate,
  onCloneTemplate,
  onCreateTemplate,
  onApplyTemplate,
}: TemplateSelectorProps): React.JSX.Element {
  const [templates, setTemplates] = useState<Template[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [selectedTag, setSelectedTag] = useState<string>('all');
  const [showCreateModal, setShowCreateModal] = useState<boolean>(false);
  const [editingTemplateId, setEditingTemplateId] = useState<number | null>(null);
  const [confirmState, setConfirmState] = useState<ConfirmState>({
    open: false,
    template: null,
    title: '删除模板',
    message: ''
  });

  // Load templates
  const loadTemplates = useCallback(async () => {
    setLoading(true);
    try {
      const result = await fetchTemplates(Number(gameGid), {
        search: searchQuery,
        type: selectedTag
      });

      if (result.success && result.data) {
        setTemplates(result.data);
      } else {
        console.error('[TemplateSelector] Failed to load templates:', result.message);
      }
    } catch (error) {
      console.error('[TemplateSelector] Error loading templates:', error);
    } finally {
      setLoading(false);
    }
  }, [gameGid, searchQuery, selectedTag]);

  // Load templates on mount
  useEffect(() => {
    loadTemplates();
  }, [loadTemplates]);

  // Search templates
  const handleSearch = useCallback((query: string) => {
    setSearchQuery(query);
  }, []);

  // Filter tags
  const handleTagSelect = useCallback((tag: string) => {
    setSelectedTag(tag);
  }, []);

  // Apply template
  const handleApplyClick = useCallback(async (template: Template) => {
    if (!onApplyTemplate) return;

    if (onTemplateSelect) {
      onTemplateSelect(template);
    }

    try {
      const result = await onApplyTemplate(template);
      if (result.success) {
              }
    } catch (error) {
      console.error('[TemplateSelector] Error applying template:', error);
    }
  }, [onApplyTemplate, onTemplateSelect]);

  // Edit template
  const handleEditTemplate = useCallback((template: Template) => {
    setEditingTemplateId(typeof template.id === 'number' ? template.id : null);
  }, []);

  // Clone template
  const handleCloneTemplate = useCallback((template: Template) => {
    if (onCloneTemplate) {
      onCloneTemplate(template);
    }
  }, [onCloneTemplate]);

  // Delete template
  const handleDeleteTemplate = useCallback(async (template: Template) => {
    if (!onDeleteTemplate) return;

    setConfirmState({
      open: true,
      template,
      title: '删除模板',
      message: `确定要删除模板 "${template.name}" 吗？此操作不可撤销！`
    });
  }, [onDeleteTemplate]);

  const handleConfirmDelete = useCallback(() => {
    if (confirmState.template && onDeleteTemplate) {
      onDeleteTemplate(confirmState.template);
      setTemplates(prev => prev.filter(t => t.id !== confirmState.template!.id));
    }
    setConfirmState(prev => ({ ...prev, open: false }));
  }, [confirmState.template, onDeleteTemplate]);

  // Handle template save
  const handleTemplateSave = useCallback((savedTemplate: Template) => {
    if (savedTemplate.id) {
      setTemplates(prev => {
        const index = prev.findIndex(t => t.id === savedTemplate.id);
        if (index >= 0) {
          const updated = [...prev];
          updated[index] = savedTemplate;
          return updated;
        }
        return [...prev, savedTemplate];
      });
    } else {
      setTemplates(prev => [...prev, savedTemplate]);
    }
    setEditingTemplateId(null);
  }, []);

  // Handle template delete
  const handleTemplateDelete = useCallback(() => {
    loadTemplates();
  }, [loadTemplates]);

  const handleCancelDelete = useCallback(() => {
    setConfirmState(prev => ({ ...prev, open: false }));
  }, []);

  // Create new template
  const handleCreateTemplate = useCallback(() => {
    setShowCreateModal(true);
  }, []);

  const handleCloseCreateModal = useCallback(() => {
    setShowCreateModal(false);
  }, []);

  return (
    <>
      <div className="template-selector">
        {/* Header */}
        <div className="template-selector-header">
          <div className="header-content">
            <div>
              <h3 className="title">📋 模板系统</h3>
              <p className="subtitle">快速创建和复用查询模板</p>
            </div>
            <Button
              variant="primary"
              onClick={() => setEditingTemplateId(null)}
              className="create-template-btn"
            >
              <i className="bi bi-plus-lg"></i>
              新建模板
            </Button>
          </div>
        </div>

        {/* Tags Filter */}
        <div className="tags-filter">
          <div className="filter-container">
            <button
              className={`tag-btn ${selectedTag === 'all' ? 'active' : ''}`}
              onClick={() => handleTagSelect('all')}
            >
              全部模板
            </button>
            {['event', 'join', 'union_all', 'output'].map(tag => (
              <button
                key={tag}
                className={`tag-btn ${selectedTag === tag ? 'active' : ''}`}
                onClick={() => handleTagSelect(tag)}
              >
                {tag}
              </button>
            ))}
          </div>
        </div>

        {/* Search Bar */}
        <div className="search-bar">
          <i className="bi bi-search"></i>
          <Input
            type="text"
            value={searchQuery}
            onChange={(e) => handleSearch(e.target.value)}
            placeholder="搜索模板..."
            className="search-input"
          />
          <button
            className="search-btn"
            onClick={() => loadTemplates()}
            disabled={loading}
          >
            <i className="bi-search"></i>
            搜索
          </button>
        </div>

        {/* Templates List */}
        {loading ? (
          <div className="templates-container loading">
            <div className="spinner"></div>
            <p>加载模板...</p>
          </div>
        ) : (
          <>
            {/* Empty State */}
            {templates.length === 0 && searchQuery === '' && (
              <EmptyState
                icon={<i className="bi bi-inbox" style={{ fontSize: '48px' }} />}
                title="没有找到模板"
              />
            )}

            {/* Filtered by tag */}
            {templates.length === 0 && searchQuery !== '' && (
              <EmptyState
                icon={<i className="bi bi-inbox" style={{ fontSize: '48px' }} />}
                title={`找不到"${searchQuery}"的模板`}
              />
            )}

            {/* No Templates */}
            {templates.length > 0 && (
              <div className="templates-list">
                {templates.map(template => (
                  <div key={template.id} className="template-card">
                    {/* Template Card */}
                    <div className="template-header">
                      <div className="template-name">{template.name}</div>
                      <div className="template-meta">
                        <span className="template-type">{template.type || 'event'}</span>
                        <span className="template-tags">
                          {template.tags && template.tags.map(tag => (
                            <span key={tag} className="tag-label">{tag}</span>
                          ))}
                        </span>
                      </div>
                      <div className="template-date">
                        {new Date(template.created_at).toLocaleDateString()}
                      </div>
                      <div className="template-actions">
                        {/* Edit */}
                        <button
                          onClick={() => handleEditTemplate(template)}
                          className="btn btn-sm btn-outline-primary"
                          title="编辑模板"
                        >
                          <i className="bi bi-pencil"></i>
                        </button>
                        {/* Clone */}
                        <button
                          onClick={() => handleCloneTemplate(template)}
                          className="btn btn-sm btn-outline-secondary"
                          title="复制模板"
                        >
                          <i className="bi-files"></i>
                        </button>
                        {/* Delete */}
                        <button
                          onClick={() => handleDeleteTemplate(template)}
                          className="btn btn-sm btn-outline-danger"
                          title="删除模板"
                        >
                          <i className="bi-trash"></i>
                        </button>
                      </div>
                    </div>

                    {/* Description */}
                    <div className="template-description">
                      {template.description}
                    </div>

                    {/* Apply Template */}
                    <button
                      onClick={() => handleApplyClick(template)}
                      className="btn btn-primary w-100"
                    >
                      <i className="bi-play-fill"></i>
                      应用模板
                    </button>
                  </div>
                ))}
              </div>
            )}
          </>
        )}

        {/* Template Editor */}
        <TemplateEditor
          templateId={editingTemplateId}
          gameGid={Number(gameGid)}
          isOpen={editingTemplateId !== null || showCreateModal}
          onClose={() => {
            setEditingTemplateId(null);
            setShowCreateModal(false);
          }}
          onSave={handleTemplateSave}
          onDelete={handleTemplateDelete}
        />
      </div>

      <ConfirmDialog
        open={confirmState.open}
        title={confirmState.title}
        message={confirmState.message}
        confirmText="删除"
        cancelText="取消"
        variant="danger"
        onConfirm={handleConfirmDelete}
        onCancel={handleCancelDelete}
      />
    </>
  );
}

// ⚡️ REACT PERF: React.memo + useCallback optimization
// See: docs/reports/2026-03-05/PERFORMANCE-OPTIMIZATION-DETAILED-REPORT.md

import { Input } from '@shared/ui';
import React, { useState, useCallback, memo } from 'react';
import { Link } from 'react-router-dom';
import './AlterSql.css';

/**
 * ALTER SQL页面
 * 用于生成ALTER TABLE语句
 */

// Type Definitions
interface Alteration {
  action: 'ADD' | 'DROP' | 'MODIFY';
  column: string;
  type: 'string' | 'int' | 'bigint' | 'decimal(10,2)';
}

function AlterSql(): React.JSX.Element {
  const [tableName, setTableName] = useState<string>('');
  const [alterations, setAlterations] = useState<Alteration[]>([
    { action: 'ADD', column: '', type: 'string' }
  ]);

  const addAlteration = useCallback((): void => {
    setAlterations([...alterations, { action: 'ADD', column: '', type: 'string' }]);
  }, [alterations]);

  const removeAlteration = useCallback((index: number): void => {
    setAlterations(alterations.filter((_, i) => i !== index));
  }, [alterations]);

  const updateAlteration = useCallback((index: number, field: keyof Alteration, value: string): void => {
    const newAlterations = [...alterations];
    (newAlterations[index][field] as string) = value;
    setAlterations(newAlterations);
  }, [alterations]);

  const generateSQL = useCallback((): string => {
    return alterations
      .filter(a => a.column)
      .map(a => `ALTER TABLE \${tableName} \${a.action} COLUMN \${a.column} \${a.type};`)
      .join('\n');
  }, [alterations, tableName]);

  return (
    <div className="alter-sql-container">
      <div className="page-header">
        <h1>ALTER SQL生成器</h1>
        <Link to="/hql-manage" className="btn btn-outline-secondary">
          <i className="bi bi-arrow-left"></i>
          返回
        </Link>
      </div>

      <div className="content-layout">
        <div className="config-panel glass-card">
          <h3>配置</h3>
          <Input
            label="表名"
            type="text"
            value={tableName}
            onChange={(e) => setTableName(e.target.value)}
            placeholder="表名 (例如: dwd_event_login)"
          />

          <div className="alterations-list">
            {alterations.map((alt, index) => (
              <div key={index} className="alteration-item">
                <select
                  className="form-control"
                  value={alt.action}
                  onChange={(e) => updateAlteration(index, 'action', e.target.value)}
                >
                  <option value="ADD">ADD</option>
                  <option value="DROP">DROP</option>
                  <option value="MODIFY">MODIFY</option>
                </select>
                <Input
                  type="text"
                  value={alt.column}
