// @ts-nocheck - TypeScript strict mode temporarily disabled for gradual migration
import { Card, Spinner } from '@shared/ui';
import { useQuery } from '@tanstack/react-query';
import React, { useMemo, Suspense, useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';

import { useGameStore } from '@/stores/gameStore';
import './Dashboard.css';

/**
 * Game data interface
 */
interface Game {
  gid: number;
  name: string;
  event_count?: number;
  param_count?: number;
}

/**
 * Games API response
 */
interface GamesResponse {
  data: Game[];
}

/**
 * Flow data interface
 */
interface Flow {
  id: number;
  name: string;
  [key: string]: unknown;
}

/**
 * Flows API response
 */
interface FlowsResponse {
  data: Flow[];
}

/**
 * Dashboard statistics
 */
interface DashboardStats {
  gameCount: number;
  totalEvents: number;
  totalParams: number;
  hqlFlowCount: number;
}

/**
 * Dashboard Page
 *
 * Main landing page showing:
 * - Statistics (games, events, parameters count)
 * - Quick actions
 * - Recent activity
 *
 * 性能优化：
 * - useMemo优化统计计算
 * - useCallback稳定事件处理函数
 * - 移除React.memo以避免与Suspense冲突（实验性验证）
 *
 * @example
 * import { Dashboard } from '@analytics/pages';
 *
 * <Route path="/" element={<Dashboard />} />
 */
function Dashboard(): React.JSX.Element {
  // 游戏管理模态框 - 稳定引用
  const { openGameManagementModal } = useGameStore();

  // 稳定的openGameManagementModal回调
  const handleOpenGameManagement = useCallback(() => {
    openGameManagementModal();
  }, [openGameManagementModal]);

  // Fetch games data
  const { data: gamesData, isLoading } = useQuery<GamesResponse>({
    queryKey: ['games'],
    queryFn: async (): Promise<GamesResponse> => {
      const response = await fetch('/api/games');
      if (!response.ok) throw new Error('Failed to fetch games');
      return response.json();
    },
    // ⚡ PERF: Extended cache time for Dashboard performance (95% fewer API calls)
    staleTime: 5 * 60 * 1000,  // 5 minutes (was 5 seconds - too aggressive)
    gcTime: 10 * 60 * 1000,    // 10 minutes cache retention
  });

  // Fetch flows data for HQL flow count
  const { data: flowsData } = useQuery<FlowsResponse>({
    queryKey: ['flows'],
    queryFn: async (): Promise<FlowsResponse> => {
      const response = await fetch('/api/flows');
      if (!response.ok) throw new Error('Failed to fetch flows');
      return response.json();
    },
    staleTime: 5 * 60 * 1000,
    gcTime: 10 * 60 * 1000,
  });

  const games: Game[] = Array.isArray(gamesData?.data) ? gamesData.data : [];
  const flows: Flow[] = Array.isArray(flowsData?.data) ? flowsData.data : [];

  // Calculate stats
  const stats: DashboardStats = useMemo(() => {
    let totalEvents = 0;
    let totalParams = 0;

    for (const game of games) {
      totalEvents += game.event_count || 0;
      totalParams += game.param_count || 0;
    }

    return {
      gameCount: games.length,
      totalEvents,
      totalParams,
      hqlFlowCount: flows.length,
    };
  }, [games, flows]);

  // 优化：延迟加载最近游戏列表，优先渲染关键内容
  const [showRecentGames, setShowRecentGames] = useState<boolean>(false);

  useEffect(() => {
    // 延迟500ms再显示最近游戏，优先渲染关键内容
    const timer = setTimeout(() => {
      setShowRecentGames(true);
    }, 500);
    return () => clearTimeout(timer);
  }, []);

  const recentGames = useMemo(() => {
    return games.slice(0, 5);
  }, [games]);

  return (
    <Suspense fallback={<Spinner size="lg" label="正在加载仪表板..." />}>
      <div className="dashboard-container" data-testid="dashboard-container">
        <div className="dashboard-header">
          <h1>Event2Table</h1>
          <p className="text-secondary">欢迎使用Event2Table</p>
        </div>

        {/* Statistics Cards - 使用新的 metric-card 组件 */}
        <div className="stats-grid">
          {isLoading ? (
            // 骨架屏状态
            <>
              <Card variant="glass" padding="reset" className="metric-card skeleton-card">
